201	{% block extra_js %}
202	<script>
203	    document.addEventListener('DOMContentLoaded', function () {
204	        const shareLink = document.querySelector('[data-specials-share-link]');
205	        if (!shareLink) {
206	            return;
207	        }
208	
209	        const defaultLabel = shareLink.dataset.shareLabelDefault || 'Share this day';
210	        const copiedLabel = shareLink.dataset.shareLabelCopied || 'Link copied';
211	        const shareUrl = shareLink.getAttribute('href');
212	        let copiedTimeoutId = null;
213	
214	        function resetShareLabel() {
215	            if (copiedTimeoutId) {
216	                window.clearTimeout(copiedTimeoutId);
217	                copiedTimeoutId = null;
218	            }
219	            shareLink.textContent = defaultLabel;
220	            shareLink.classList.remove('specials-toolbar__link--copied');
221	        }
222	
223	        function showCopiedState() {
224	            resetShareLabel();
225	            shareLink.textContent = copiedLabel;
226	            shareLink.classList.add('specials-toolbar__link--copied');
227	            copiedTimeoutId = window.setTimeout(() => {
228	                shareLink.textContent = defaultLabel;
229	                shareLink.classList.remove('specials-toolbar__link--copied');
230	                copiedTimeoutId = null;
231	            }, 2000);
232	        }
233	
234	        shareLink.addEventListener('click', async function (event) {
235	            if (!shareUrl) {
236	                return;
237	            }
238	
239	            event.preventDefault();
240	
241	            if (navigator.share) {
242	                try {
243	                    await navigator.share({
244	                        title: document.title,
245	                        url: shareUrl,
246	                    });
247	                    resetShareLabel();
248	                    return;
249	                } catch (error) {
250	                    if (error && error.name === 'AbortError') {
251	                        return;
252	                    }
253	                }
254	            }
255	
256	            if (navigator.clipboard && navigator.clipboard.writeText) {
257	                try {
258	                    await navigator.clipboard.writeText(shareUrl);
259	                    showCopiedState();
260	                    return;
261	                } catch (error) {
262	                    // Fall through to normal navigation below.
263	                }
264	            }
265	
266	            window.location.assign(shareUrl);
267	        });
268	    });
269	</script>
270	{% if map_points %}
271	<script>
272	    window.__specialsGoogleMapsLoaded = window.__specialsGoogleMapsLoaded || false;
273	    window.initSpecialsGoogleMap = function () {
274	        window.__specialsGoogleMapsLoaded = true;
275	        if (typeof window.__renderSpecialsGoogleMap === 'function') {
276	            window.__renderSpecialsGoogleMap();
277	        }
278	    };
279	
280	    document.addEventListener('DOMContentLoaded', function () {
281	        const mapElement = document.getElementById('specials-map');
282	        const pointsElement = document.getElementById('specials-map-points');
283	        if (!mapElement || !pointsElement) {
284	            return;
285	        }
286	
287	        const points = JSON.parse(pointsElement.textContent || '[]');
288	        if (!Array.isArray(points) || points.length === 0) {
289	            return;
290	        }
291	
292	        let map = null;
293	        let bounds = null;
294	        let infoWindow = null;
295	        const markersByPointId = new Map();
296	        const cardsByPointId = new Map();
297	        const cardElements = Array.from(document.querySelectorAll('.special-card[data-map-point-id]'));
298	        let activePointId = '';
299	
300	        function escapeHtml(value) {
301	            return String(value || '').replace(/[&<>"']/g, (char) => ({
302	                '&': '&amp;',
303	                '<': '&lt;',
304	                '>': '&gt;',
305	                '"': '&quot;',
306	                "'": '&#39;',
307	            }[char]));
308	        }
309	
310	        function buildMarkerIcon(fillColor, scale, strokeWeight) {
311	            return {
312	                path: google.maps.SymbolPath.CIRCLE,
313	                fillColor,
314	                fillOpacity: 0.92,
315	                strokeColor: '#ffffff',
316	                strokeOpacity: 1,
317	                strokeWeight,
318	                scale,
319	            };
320	        }
321	
322	        cardElements.forEach((card) => {
323	            const pointId = card.dataset.mapPointId;
324	            if (!pointId) {
325	                return;
326	            }
327	            if (!cardsByPointId.has(pointId)) {
328	                cardsByPointId.set(pointId, []);
329	            }
330	            cardsByPointId.get(pointId).push(card);
331	        });
332	
333	        function renderPopup(point) {
334	            const titles = point.special_titles
335	                .map((title) => `<li>${escapeHtml(title)}</li>`)
336	                .join('');
337	            const directions = point.google_maps_uri
338	                ? `<a class="specials-map-popup__link" href="${escapeHtml(point.google_maps_uri)}" target="_blank" rel="noopener">Open in Google Maps</a>`
339	                : '';
340	            return `
341	                <div class="specials-map-popup">
342	                    <div class="specials-map-popup__venue">${escapeHtml(point.venue_label)}</div>
343	                    ${point.address ? `<div class="specials-map-popup__address">${escapeHtml(point.address)}</div>` : ''}
344	                    <ul class="specials-map-popup__list">${titles}</ul>
345	                    <div class="specials-map-popup__actions">
346	                        <button type="button" class="specials-map-popup__focus" data-specials-map-focus="${point.point_id}">
347	                            See these specials
348	                        </button>
349	                        ${directions}
350	                    </div>
351	                </div>
352	            `;
353	        }
354	
355	        function flashCards(pointId) {
356	            const cards = cardsByPointId.get(pointId) || [];
357	            cards.forEach((card) => {
358	                if (card._specialsMapFlashTimeout) {
359	                    window.clearTimeout(card._specialsMapFlashTimeout);
360	                }
361	                card.classList.remove('special-card--map-flash');
362	                void card.offsetWidth;
363	                card.classList.add('special-card--map-flash');
364	                card._specialsMapFlashTimeout = window.setTimeout(() => {
365	                    card.classList.remove('special-card--map-flash');
366	                    card._specialsMapFlashTimeout = null;
367	                }, 1600);
368	            });
369	        }
370	
371	        function setActivePoint(pointId, options = {}) {
372	            const { pan = false, openPopup = false, scroll = false, flash = false } = options;
373	
374	            if (activePointId && markersByPointId.has(activePointId)) {
375	                markersByPointId.get(activePointId).setIcon(buildMarkerIcon('#45B7D1', 9, 2));
376	                (cardsByPointId.get(activePointId) || []).forEach((card) => {
377	                    card.classList.remove('special-card--map-active');
378	                });
379	            }
380	
381	            activePointId = pointId || '';
382	            if (!activePointId || !markersByPointId.has(activePointId)) {
383	                return;
384	            }
385	
386	            const marker = markersByPointId.get(activePointId);
387	            marker.setIcon(buildMarkerIcon('#FF6B6B', 11, 3));
388	
389	            const cards = cardsByPointId.get(activePointId) || [];
390	            cards.forEach((card) => {
391	                card.classList.add('special-card--map-active');
392	            });
393	
394	            if (pan && map) {
395	                map.panTo(marker.getPosition());
396	            }
397	            if (openPopup) {
398	                infoWindow.setContent(renderPopup(points.find((point) => point.point_id === activePointId)));
399	                infoWindow.open({ anchor: marker, map });
400	            }
401	            if (scroll && cards.length) {
402	                cards[0].scrollIntoView({ behavior: 'smooth', block: 'center' });
403	            }
404	            if (flash && cards.length) {
405	                const flashDelay = scroll ? 320 : 0;
406	                window.setTimeout(() => {
407	                    flashCards(activePointId);
408	                }, flashDelay);
409	            }
410	        }
411	
412	        function renderMap() {
413	            if (map || !window.__specialsGoogleMapsLoaded || !(window.google && google.maps)) {
414	                return map;
415	            }
416	
417	            map = new google.maps.Map(mapElement, {
418	                mapTypeControl: false,
419	                streetViewControl: false,
420	                fullscreenControl: true,
421	                zoomControl: true,
422	                gestureHandling: 'cooperative',
423	            });
424	            bounds = new google.maps.LatLngBounds();
425	            infoWindow = new google.maps.InfoWindow();
426	
427	            points.forEach((point) => {
428	                const marker = new google.maps.Marker({
429	                    map,
430	                    position: { lat: point.latitude, lng: point.longitude },
431	                    title: point.venue_label,
432	                    icon: buildMarkerIcon('#45B7D1', 9, 2),
433	                });
434	                marker.addListener('click', () => {
435	                    setActivePoint(point.point_id, { scroll: true, pan: true, openPopup: true, flash: true });
436	                });
437	                markersByPointId.set(point.point_id, marker);
438	                bounds.extend(marker.getPosition());
439	            });
440	
441	            google.maps.event.addListener(infoWindow, 'domready', () => {
442	                if (!activePointId) {
443	                    return;
444	                }
445	                const focusButton = document.querySelector(`[data-specials-map-focus="${activePointId}"]`);
446	                if (!focusButton) {
