{% extends "regions/base_public.html" %}

{% block content %}
<div class="specials-page">
    <div class="specials-topbar">
        <div class="specials-topbar__inner">
            <span class="specials-topbar__text">Plan your {{ region.name }} trip with ClanCal</span>
            <div class="specials-topbar__actions">
                <a href="{% url 'account_signup' %}?region={{ region.id }}" class="btn btn-primary btn-sm">Get Started Free</a>
                <a href="{% url 'account_login' %}" class="btn btn-outline-dark btn-sm">Sign In</a>
            </div>
        </div>
    </div>
    <section class="specials-hero" style="--hero-image: url('{{ region.hero_image_url|default:"https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=1600" }}');">
        <div class="specials-hero__overlay"></div>
        <div class="specials-hero__content">
            <nav class="region-breadcrumb">
                <a href="{% url 'regions:explore' %}">Explore</a>
                <span class="separator">/</span>
                <a href="{% url 'regions:region_detail' slug=region.slug %}">{{ region.name }}</a>
                <span class="separator">/</span>
                <span class="current">Specials</span>
            </nav>

            <div class="specials-hero__eyebrow">
                {% if is_today_specials %}Today's Specials{% else %}Daily Archive{% endif %}
            </div>
            <h1 class="specials-hero__title">
                {% if is_today_specials %}
                What's on the board in {{ region.name }}
                {% else %}
                Specials for {{ target_date|date:"l, F j, Y" }}
                {% endif %}
            </h1>
            <p class="specials-hero__subtitle">
                {{ target_date|date:"l, F j, Y" }} • {{ special_count }} stop{{ special_count|pluralize }} worth checking
            </p>

            <div class="specials-toolbar">
                <a href="{{ previous_day_url }}" class="specials-toolbar__link">
                    <i class="bi bi-arrow-left"></i>
                    Previous day
                </a>
                {% if not is_today_specials %}
                <a href="{{ today_specials_url }}" class="specials-toolbar__link specials-toolbar__link--primary">
                    Today's specials
                </a>
                {% endif %}
                <a href="{{ archive_url }}"
                   class="specials-toolbar__link"
                   data-specials-share-link
                   data-share-label-default="Share this day"
                   data-share-label-copied="Link copied">
                    Share this day
                </a>
                {% if show_next_day %}
                <a href="{{ next_day_url }}" class="specials-toolbar__link">
                    Next day
                    <i class="bi bi-arrow-right"></i>
                </a>
                {% endif %}
            </div>

            {% if meal_period_options %}
            <div class="specials-filters" role="navigation" aria-label="Filter specials by meal period">
                <a href="{% if is_today_specials %}{% url 'regions:region_specials_today' slug=region.slug %}{% else %}{% url 'regions:region_specials_day' slug=region.slug date=target_date|date:'Y-m-d' %}{% endif %}"
                   class="specials-filters__chip {% if not selected_meal_period %}specials-filters__chip--active{% endif %}">
                    All
                </a>
                {% for value, label in meal_period_options %}
                <a href="{% if is_today_specials %}{% url 'regions:region_specials_today' slug=region.slug %}{% else %}{% url 'regions:region_specials_day' slug=region.slug date=target_date|date:'Y-m-d' %}{% endif %}?meal_period={{ value }}"
                   class="specials-filters__chip {% if selected_meal_period == value %}specials-filters__chip--active{% endif %}">
                    {{ label }}
                </a>
                {% endfor %}
            </div>
            {% endif %}
        </div>
    </section>

    <section class="specials-listing">
        <div class="container">
            {% if specials %}
            <div class="specials-layout{% if map_points %} specials-layout--with-map{% endif %}">
                {% if map_points %}
                <aside class="specials-map-panel">
                    <div class="specials-map-card">
                        <div class="specials-map-card__eyebrow">Pinpoint the board</div>
                        <h2 class="specials-map-card__title">Follow the flavor trail</h2>
                        <p class="specials-map-card__copy">
                            Confirmed stops are pinned so people can quickly see what’s nearby and decide which special is worth the detour.
                        </p>
                        <div class="specials-map-card__stats">
                            <span>{{ map_points|length }} pinned stop{{ map_points|pluralize }}</span>
                            <span>{{ special_count }} special{{ special_count|pluralize }} on the board</span>
                        </div>
                        <div id="specials-map" class="specials-map" aria-label="Map of confirmed specials locations"></div>
                    </div>
                    {{ map_points|json_script:"specials-map-points" }}
                </aside>
                {% endif %}

                <div class="specials-results">
            <div class="specials-grid">
                {% for special in specials %}
                <article class="special-card"
                         data-special-id="{{ special.event.id }}"
                         {% if special.map_point_id %}data-map-point-id="{{ special.map_point_id }}"{% endif %}>
                    <div class="special-card__media {% if special.detail.hero_mode == 'image' %}special-card__media--image{% endif %}"
                         {% if special.detail.hero_mode == "image" %}style="background-image: linear-gradient(180deg, rgba(16, 24, 32, 0.18), rgba(16, 24, 32, 0.72)), url('{{ special.detail.hero_image_url }}');"{% endif %}>
                        <span class="special-card__badge">Food & Dining</span>
                        {% if special.detail.meal_period_label %}
                        <span class="special-card__badge special-card__badge--meal">{{ special.detail.meal_period_label }}</span>
                        {% elif special.detail.time_label == "All day" %}
                        <span class="special-card__badge special-card__badge--time">{{ special.detail.time_label }}</span>
                        {% endif %}
                        {% if special.event.is_recurring %}
                        <span class="special-card__recurring">{{ special.event.get_recurrence_pattern_display }}</span>
                        {% elif special.is_occurrence %}
                        <span class="special-card__recurring">Multi-day special</span>
                        {% endif %}
                    </div>

                    <div class="special-card__body">
                        <div class="special-card__header">
                            <div>
                                <h2 class="special-card__title">{{ special.detail.display_title }}</h2>
                                {% with venue_label=special.event.matched_business.display_name|default:special.event.location %}
                                {% if venue_label %}
                                <div class="special-card__location">
                                    <i class="bi bi-geo-alt"></i>
                                    <span>{{ venue_label }}</span>
                                </div>
                                {% endif %}
                                {% endwith %}
                                {% if special.event.address %}
                                <div class="special-card__address">{{ special.event.address }}</div>
                                {% endif %}
                            </div>
                            {% if special.detail.time_label and special.detail.time_label != "All day" %}
                            <div class="special-card__time">{{ special.detail.time_label }}</div>
                            {% endif %}
                        </div>

                        {% if special.detail.lede %}
                        <p class="special-card__lede">{{ special.detail.lede }}</p>
                        {% endif %}

                        {% if special.detail.menu_items %}
                        <ul class="special-card__menu">
                            {% for item in special.detail.menu_items %}
                            <li>{{ item }}</li>
                            {% endfor %}
                        </ul>
                        {% endif %}

                        {% if special.detail.promo_items %}
                        <ul class="special-card__promo-list">
                            {% for item in special.detail.promo_items %}
                            <li class="special-card__promo-item">{{ item }}</li>
                            {% endfor %}
                        </ul>
                        {% endif %}

                        {% if special.detail.detail_lines %}
                        <div class="special-card__copy">
                            {% for line in special.detail.detail_lines %}
                            <p>{{ line }}</p>
                            {% endfor %}
                        </div>
                        {% endif %}

                        <div class="special-card__actions">
                            <a href="{{ special.url }}" class="btn btn-primary">
                                View details
                            </a>
                            {% if special.event.google_maps_uri %}
                            <a href="{{ special.event.google_maps_uri }}" target="_blank" rel="noopener" class="btn btn-outline-secondary">
                                Open map
                            </a>
                            {% endif %}
                        </div>
                    </div>
                </article>
                {% endfor %}
            </div>
                </div>
            </div>
            {% else %}
            <div class="empty-state specials-empty-state">
                <i class="bi bi-cup-hot"></i>
                <p>No specials are posted for {{ target_date|date:"l, F j, Y" }} yet.</p>
                <a href="{{ today_specials_url }}" class="btn btn-primary">See today's page</a>
            </div>
            {% endif %}
        </div>
    </section>
</div>
{% endblock %}

{% block extra_js %}
<script>
    document.addEventListener('DOMContentLoaded', function () {
        const shareLink = document.querySelector('[data-specials-share-link]');
        if (!shareLink) {
            return;
        }

        const defaultLabel = shareLink.dataset.shareLabelDefault || 'Share this day';
        const copiedLabel = shareLink.dataset.shareLabelCopied || 'Link copied';
        const shareUrl = shareLink.getAttribute('href');
        let copiedTimeoutId = null;

        function resetShareLabel() {
            if (copiedTimeoutId) {
                window.clearTimeout(copiedTimeoutId);
                copiedTimeoutId = null;
            }
            shareLink.textContent = defaultLabel;
            shareLink.classList.remove('specials-toolbar__link--copied');
        }

        function showCopiedState() {
            resetShareLabel();
            shareLink.textContent = copiedLabel;
            shareLink.classList.add('specials-toolbar__link--copied');
            copiedTimeoutId = window.setTimeout(() => {
                shareLink.textContent = defaultLabel;
                shareLink.classList.remove('specials-toolbar__link--copied');
                copiedTimeoutId = null;
            }, 2000);
        }

        shareLink.addEventListener('click', async function (event) {
            if (!shareUrl) {
                return;
            }

            event.preventDefault();

            if (navigator.share) {
                try {
                    await navigator.share({
                        title: document.title,
                        url: shareUrl,
                    });
                    resetShareLabel();
                    return;
                } catch (error) {
                    if (error && error.name === 'AbortError') {
                        return;
                    }
                }
            }

            if (navigator.clipboard && navigator.clipboard.writeText) {
                try {
                    await navigator.clipboard.writeText(shareUrl);
                    showCopiedState();
                    return;
                } catch (error) {
                    // Fall through to normal navigation below.
                }
            }

            window.location.assign(shareUrl);
        });
    });
</script>
{% if map_points %}
<script>
    window.__specialsGoogleMapsLoaded = window.__specialsGoogleMapsLoaded || false;
    window.initSpecialsGoogleMap = function () {
        window.__specialsGoogleMapsLoaded = true;
        if (typeof window.__renderSpecialsGoogleMap === 'function') {
            window.__renderSpecialsGoogleMap();
        }
    };

    document.addEventListener('DOMContentLoaded', function () {
        const mapElement = document.getElementById('specials-map');
        const pointsElement = document.getElementById('specials-map-points');
        if (!mapElement || !pointsElement) {
            return;
        }

        const points = JSON.parse(pointsElement.textContent || '[]');
        if (!Array.isArray(points) || points.length === 0) {
            return;
        }

        let map = null;
        let bounds = null;
        let infoWindow = null;
        const markersByPointId = new Map();
        const cardsByPointId = new Map();
        const cardElements = Array.from(document.querySelectorAll('.special-card[data-map-point-id]'));
        let activePointId = '';

        function escapeHtml(value) {
            return String(value || '').replace(/[&<>"']/g, (char) => ({
                '&': '&amp;',
                '<': '&lt;',
                '>': '&gt;',
                '"': '&quot;',
                "'": '&#39;',
            }[char]));
        }

        function buildMarkerIcon(fillColor, scale, strokeWeight) {
            return {
                path: google.maps.SymbolPath.CIRCLE,
                fillColor,
                fillOpacity: 0.92,
                strokeColor: '#ffffff',
                strokeOpacity: 1,
                strokeWeight,
                scale,
            };
        }

        cardElements.forEach((card) => {
            const pointId = card.dataset.mapPointId;
            if (!pointId) {
                return;
            }
            if (!cardsByPointId.has(pointId)) {
                cardsByPointId.set(pointId, []);
            }
            cardsByPointId.get(pointId).push(card);
        });

        function renderPopup(point) {
            const titles = point.special_titles
                .map((title) => `<li>${escapeHtml(title)}</li>`)
                .join('');
            const directions = point.google_maps_uri
                ? `<a class="specials-map-popup__link" href="${escapeHtml(point.google_maps_uri)}" target="_blank" rel="noopener">Open in Google Maps</a>`
                : '';
            return `
                <div class="specials-map-popup">
                    <div class="specials-map-popup__venue">${escapeHtml(point.venue_label)}</div>
                    ${point.address ? `<div class="specials-map-popup__address">${escapeHtml(point.address)}</div>` : ''}
                    <ul class="specials-map-popup__list">${titles}</ul>
                    <div class="specials-map-popup__actions">
                        <button type="button" class="specials-map-popup__focus" data-specials-map-focus="${point.point_id}">
                            See these specials
                        </button>
                        ${directions}
                    </div>
                </div>
            `;
        }

        function flashCards(pointId) {
            const cards = cardsByPointId.get(pointId) || [];
            cards.forEach((card) => {
                if (card._specialsMapFlashTimeout) {
                    window.clearTimeout(card._specialsMapFlashTimeout);
                }
                card.classList.remove('special-card--map-flash');
                void card.offsetWidth;
                card.classList.add('special-card--map-flash');
                card._specialsMapFlashTimeout = window.setTimeout(() => {
                    card.classList.remove('special-card--map-flash');
                    card._specialsMapFlashTimeout = null;
                }, 1600);
            });
        }

        function setActivePoint(pointId, options = {}) {
            const { pan = false, openPopup = false, scroll = false, flash = false } = options;

            if (activePointId && markersByPointId.has(activePointId)) {
                markersByPointId.get(activePointId).setIcon(buildMarkerIcon('#45B7D1', 9, 2));
                (cardsByPointId.get(activePointId) || []).forEach((card) => {
                    card.classList.remove('special-card--map-active');
                });
            }

            activePointId = pointId || '';
            if (!activePointId || !markersByPointId.has(activePointId)) {
                return;
            }

            const marker = markersByPointId.get(activePointId);
            marker.setIcon(buildMarkerIcon('#FF6B6B', 11, 3));

            const cards = cardsByPointId.get(activePointId) || [];
            cards.forEach((card) => {
                card.classList.add('special-card--map-active');
            });

            if (pan && map) {
                map.panTo(marker.getPosition());
            }
            if (openPopup) {
                infoWindow.setContent(renderPopup(points.find((point) => point.point_id === activePointId)));
                infoWindow.open({ anchor: marker, map });
            }
            if (scroll && cards.length) {
                cards[0].scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
            if (flash && cards.length) {
                const flashDelay = scroll ? 320 : 0;
                window.setTimeout(() => {
                    flashCards(activePointId);
                }, flashDelay);
            }
        }

        function renderMap() {
            if (map || !window.__specialsGoogleMapsLoaded || !(window.google && google.maps)) {
                return map;
            }

            map = new google.maps.Map(mapElement, {
                mapTypeControl: false,
                streetViewControl: false,
                fullscreenControl: true,
                zoomControl: true,
                gestureHandling: 'cooperative',
            });
            bounds = new google.maps.LatLngBounds();
            infoWindow = new google.maps.InfoWindow();

            points.forEach((point) => {
                const marker = new google.maps.Marker({
                    map,
                    position: { lat: point.latitude, lng: point.longitude },
                    title: point.venue_label,
                    icon: buildMarkerIcon('#45B7D1', 9, 2),
                });
                marker.addListener('click', () => {
                    setActivePoint(point.point_id, { scroll: true, pan: true, openPopup: true, flash: true });
                });
                markersByPointId.set(point.point_id, marker);
                bounds.extend(marker.getPosition());
            });

            google.maps.event.addListener(infoWindow, 'domready', () => {
                if (!activePointId) {
                    return;
                }
                const focusButton = document.querySelector(`[data-specials-map-focus="${activePointId}"]`);
                if (!focusButton) {
                    return;
                }
                focusButton.addEventListener('click', () => {
                    setActivePoint(activePointId, { pan: true, openPopup: true, scroll: true, flash: true });
                });
            });

            if (points.length === 1) {
                map.setCenter({ lat: points[0].latitude, lng: points[0].longitude });
                map.setZoom(13);
            } else {
                map.fitBounds(bounds, 48);
            }

            return map;
        }

        window.__renderSpecialsGoogleMap = renderMap;
        if (window.__specialsGoogleMapsLoaded) {
            renderMap();
        }

        cardElements.forEach((card) => {
            const pointId = card.dataset.mapPointId;
            if (!pointId) {
                return;
            }
            card.addEventListener('mouseenter', () => {
                setActivePoint(pointId);
            });
            card.addEventListener('focusin', () => {
                setActivePoint(pointId);
            });
            card.addEventListener('click', (event) => {
                if (event.target.closest('a, button')) {
                    return;
                }
                setActivePoint(pointId, { pan: true, openPopup: true });
            });
        });
    });
</script>
<script async
        src="https://maps.googleapis.com/maps/api/js?key={{ google_maps_api_key|urlencode }}&callback=initSpecialsGoogleMap&loading=async"></script>
{% endif %}
{% endblock %}

